/* Local Herd Register presentation. Mirrors counts/herd-register's search/register/import flow;
   no production API writes and no synthetic animal rows. */
const AnimalRegisterModel={
 columns:['animal_name','animal_identifier_1','animal_identifier_2','species_id','breed','sex','stage','shed_tag','park','pen','weight_kg','notes'],
 workbookColumns(data,species){return this.columns.filter(k=>!(k==='breed'&&!this.options(data,'breeds',species).length)&&!(k==='stage'&&!this.options(data,'lifecycle_stages',species).length)&&!(k==='shed_tag'&&!this.options(data,'shed_tags',species).length));},
 workbook(data,species,xlsx=window.XLSX){this.species(data,species);const columns=this.workbookColumns(data,species),sheet=xlsx.utils.aoa_to_sheet([columns,columns.map(k=>k==='species_id'?this.species(data,species).name:'')]),options=xlsx.utils.aoa_to_sheet(this.parse(this.reference(data,species)));sheet['!cols']=columns.map(()=>({wch:24}));for(let row=1;row<=100;row++)for(const key of ['animal_identifier_1','animal_identifier_2']){const address=xlsx.utils.encode_cell({r:row,c:columns.indexOf(key)});sheet[address]={t:'s',v:'',z:'@'};}sheet['!ref']=xlsx.utils.encode_range({s:{r:0,c:0},e:{r:100,c:columns.length-1}});const book=xlsx.utils.book_new();xlsx.utils.book_append_sheet(book,sheet,'Animals');xlsx.utils.book_append_sheet(book,options,'Options');return book;},
 readWorkbook(data,bytes,species,xlsx=window.XLSX){const book=xlsx.read(bytes,{type:'array',cellFormula:true}),sheet=book.Sheets.Animals;if(!sheet)throw Error('Workbook must contain the Animals sheet.');const range=xlsx.utils.decode_range(sheet['!ref']||'A1');if(range.e.r>10000||range.e.c>30)throw Error('Use at most 10,000 rows and the generated columns.');for(const [address,cell] of Object.entries(sheet)){if(address[0]==='!')continue;if(cell.f)throw Error('Formulas are not allowed in animal imports.');}const rows=xlsx.utils.sheet_to_json(sheet,{header:1,raw:true,defval:'',blankrows:false}),headers=rows.shift()||[],expected=this.workbookColumns(data,species);if(headers.length!==expected.length||headers.some((v,i)=>v!==expected[i]))throw Error('Use the animal-specific template columns in their original order.');for(const key of ['animal_identifier_1','animal_identifier_2']){const col=headers.indexOf(key);for(let row=1;row<=range.e.r;row++){const cell=sheet[xlsx.utils.encode_cell({r:row,c:col})];if(cell?.t==='n')throw Error('RFID values must be stored as text to preserve leading zeros.');}}return this.csv([this.columns,...rows.filter(r=>r.some(v=>v!=='')).map(r=>this.columns.map(k=>r[headers.indexOf(k)]??''))]);},
 location(data,kind,name,parentId=''){if(!['parks','pens'].includes(kind))throw Error('Choose a park or pen.');const next=structuredClone(data),record=EntityRegistryModel.save(next,kind,{name,parentId});return {data:next,record};},
 csv(rows){return rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n')+'\r\n';},
 parse(text){const rows=[];let row=[],cell='',quoted=false,closed=false;const input=String(text).replace(/^\uFEFF/,'');for(let i=0;i<input.length;i++){const c=input[i];if(quoted){if(c==='"'){if(input[i+1]==='"'){cell+='"';i++;}else{quoted=false;closed=true;}}else cell+=c;continue;}if(c==='"'){if(cell||closed)throw Error('Unexpected quote in CSV.');quoted=true;}else if(c===','||c==='\n'||c==='\r'){row.push(cell);cell='';closed=false;if(c!==','){if(c==='\r'&&input[i+1]==='\n')i++;if(row.some(v=>v!==''))rows.push(row);row=[];}}else{if(closed)throw Error('Unexpected text after quoted CSV value.');cell+=c;}}if(quoted)throw Error('Unclosed quoted CSV value.');row.push(cell);if(row.some(v=>v!==''))rows.push(row);return rows;},
 options(data,kind,species){return EntityRegistryModel.rows(data,kind).filter(r=>r.active&&(!['breeds','lifecycle_stages','shed_tags'].includes(kind)||r.parentId===species));},
 species(data,id){const r=this.options(data,'species').find(r=>r.id===id);if(!r)throw Error('Choose an active animal type.');return r;},
 template(data,species){this.species(data,species);return this.csv([this.columns,this.columns.map(k=>k==='species_id'?this.species(data,species).name:'')]);},
 reference(data,species){this.species(data,species);return this.csv([['field','id','name','parent_id'],...Object.entries({species_id:'species',breed:'breeds',sex:'sex_values',stage:'lifecycle_stages',shed_tag:'shed_tags',park:'parks',pen:'pens'}).flatMap(([field,kind])=>this.options(data,kind,species).filter(r=>field!=='species_id'||r.id===species).map(r=>[field,r.id,r.name,r.parentId||'']))]);},
 resolve(data,kind,value,species,parent){if(!value)return '';const rows=this.options(data,kind,species).filter(r=>!parent||r.parentId===parent);const exact=rows.find(r=>r.id===value);if(exact)return exact.id;const matches=rows.filter(r=>r.name.toLowerCase()===value.toLowerCase());if(matches.length!==1)throw Error('Choose a configured '+EntityRegistryModel.def(kind).singular+': '+value);return matches[0].id;},
 input(data,row,species){this.species(data,species);const rowSpecies=row.species_id?this.resolve(data,'species',row.species_id,species):species;if(rowSpecies!==species)throw Error('Animal type must match the selected template.');if(!String(row.animal_identifier_1||'').trim()&&!String(row.animal_identifier_2||'').trim())throw Error('Enter at least one RFID / animal identifier.');const park=this.resolve(data,'parks',row.park,species);if(!park)throw Error('Park is required.');const pen=this.resolve(data,'pens',row.pen,species,park);if(!pen)throw Error('Pen is required.');return {name:String(row.animal_name||'').trim()||row.animal_identifier_1||row.animal_identifier_2,tag1:row.animal_identifier_1,tag2:row.animal_identifier_2,species,breed:this.resolve(data,'breeds',row.breed,species),sex:this.resolve(data,'sex_values',row.sex,species),stage:this.resolve(data,'lifecycle_stages',row.stage,species),shedTag:this.resolve(data,'shed_tags',row.shed_tag,species),parentId:pen,weightKg:row.weight_kg,notes:row.notes};},
 preview(data,text,species){this.species(data,species);const parsed=this.parse(text),header=parsed.shift();if(!header||header.length!==this.columns.length||header.some((v,i)=>v!==this.columns[i]))throw Error('Use the generated template columns in their original order.');if(!parsed.length)throw Error('Add at least one animal row.');if(parsed.length>10000)throw Error('Use at most 10,000 rows.');const draft=structuredClone(data),rows=[];parsed.forEach((values,index)=>{let error='',saved=null;const raw=Object.fromEntries(this.columns.map((k,i)=>[k,String(values[i]??'').trim()]));try{if(values.length!==header.length)throw Error('Wrong number of columns.');saved=EntityRegistryModel.save(draft,'animals',this.input(draft,raw,species));}catch(e){error=e.message;}rows.push({line:index+2,raw,error,id:saved?.id});});return {rows,valid:rows.every(r=>!r.error),data:draft};},
 commit(data,text,species){const preview=this.preview(data,text,species);if(!preview.valid)throw Error('Fix all row errors before importing.');return preview.data;}
};
let animalRegisterMode='list',animalRegisterSpecies='',animalRegisterPark='',animalImportSpecies='',animalImportText='',animalImportPreview=null,animalEditingId='';
const animalBaseRenderItems=renderItems,animalBaseRecordAdd=recordAdd,animalBaseRecordEdit=recordEdit;
renderItems=function(){animalBaseRenderItems();if(recordSelection==='entity:animals')renderAnimalRegister();};
recordAdd=function(){if(recordSelection==='entity:animals')return animalEdit();return animalBaseRecordAdd();};
recordEdit=function(id,sourceId){if(recordSelection==='entity:animals')return animalEdit(id);return animalBaseRecordEdit(id,sourceId);};
function animalName(data,kind,id){return EntityRegistryModel.rows(data,kind).find(r=>r.id===id)?.name||'—';}
function animalSelectOptions(kind,value='',species='',parent=''){return AnimalRegisterModel.options(entityRegistryData(),kind,species).filter(r=>!parent||r.parentId===parent).map(r=>`<option value="${esc(r.id)}" ${r.id===value?'selected':''}>${esc(r.name)}</option>`).join('');}
function renderAnimalRegister(){const host=$('.records-content');if(!host)return;host.classList.remove('records-no-subcategory');if(animalRegisterMode==='import'){renderAnimalImport();return;}host.classList.add('animal-register');host.innerHTML=`<div class="records-title"><div><span class="eyebrow">Animal identities</span><h2>Herd Register</h2></div><div class="actions"><button onclick="animalOpenImport()" ${canEdit()?'':'disabled'}>Import animals</button><button class="primary" onclick="animalEdit()" ${canEdit()?'':'disabled'}>+ Add animal</button></div></div><div class="animal-toolbar"><label>Search<input value="${esc(recordSearch)}" placeholder="RFID or animal name" oninput="recordSearch=this.value;renderAnimalRows()"></label><label>Animal type<select onchange="animalRegisterSpecies=this.value;renderAnimalRows()"><option value="">All types</option>${animalSelectOptions('species',animalRegisterSpecies)}</select></label><label>Park<select onchange="animalRegisterPark=this.value;renderAnimalRows()"><option value="">All parks</option>${animalSelectOptions('parks',animalRegisterPark)}</select></label><label>Status<select onchange="recordStatus=this.value;renderAnimalRows()"><option value="active" ${recordStatus==='active'?'selected':''}>Active</option><option value="all" ${recordStatus==='all'?'selected':''}>All</option><option value="archived" ${recordStatus==='archived'?'selected':''}>Archived</option></select></label></div><div class="records-table-wrap"><table class="records-table"><thead><tr>${['Animal','RFID 1','RFID 2','Type','Breed','Sex','Stage','Park','Pen','Status',''].map(v=>'<th>'+v+'</th>').join('')}</tr></thead><tbody id="animal-register-rows"></tbody></table></div><div class="records-footer">Saved in this browser · Local prototype</div>`;renderAnimalRows();}
function renderAnimalRows(){const d=entityRegistryData();const rows=EntityRegistryModel.rows(d,'animals').filter(r=>{const pen=EntityRegistryModel.rows(d,'pens').find(p=>p.id===r.parentId);return (!animalRegisterSpecies||r.species===animalRegisterSpecies)&&(!animalRegisterPark||pen?.parentId===animalRegisterPark)&&(recordStatus==='all'||r.active===(recordStatus==='active'))&&[r.name,r.tag1,r.tag2].some(v=>String(v||'').toLowerCase().includes(recordSearch.toLowerCase()));});$('#animal-register-rows').innerHTML=rows.map(r=>{const pen=EntityRegistryModel.rows(d,'pens').find(p=>p.id===r.parentId);return `<tr>${[r.name,r.tag1||'—',r.tag2||'—',animalName(d,'species',r.species),animalName(d,'breeds',r.breed),animalName(d,'sex_values',r.sex),animalName(d,'lifecycle_stages',r.stage),animalName(d,'parks',pen?.parentId),pen?.name||'—'].map((v,i)=>'<td>'+(i===0?`<button class="record-name" onclick="animalEdit('${r.id}')">${esc(v)}</button>`:esc(v))+'</td>').join('')}<td><span class="status-pill ${r.active?'active':'archived'}">${r.active?'Active':'Archived'}</span></td><td><button onclick="animalEdit('${r.id}')">${canEdit()?'Edit':'View'}</button></td></tr>`;}).join('')||'<tr><td colspan="11"><div class="empty">No animals match. Add an animal or import a completed template.</div></td></tr>';}
function animalEdit(id=''){animalEditingId=id;const d=entityRegistryData(),r=EntityRegistryModel.rows(d,'animals').find(r=>r.id===id)||{},pen=EntityRegistryModel.rows(d,'pens').find(p=>p.id===r.parentId),species=r.species||animalRegisterSpecies||AnimalRegisterModel.options(d,'species')[0]?.id||'',park=pen?.parentId||'';const input=(key,label,value,type='text')=>`<label>${label}<input id="animal-${key}" type="${type}" value="${esc(value??'')}"  ${type==='number'?'min="0" step="any"':''}></label>`;const select=(key,label,kind,value,parent='')=>`<label>${label}${['species','park','pen'].includes(key)?' *':''}<select id="animal-${key}" ${['species','park'].includes(key)?`onchange="animalRefreshOptions('${key}')"`:''} ${['species','park','pen'].includes(key)?'required':''}><option value="">Choose…</option>${animalSelectOptions(kind,value,species,parent)}</select></label>`;modal(id?'Animal details':'Add animal',`<form onsubmit="event.preventDefault();animalSave()"><p class="animal-required-hint">* Required · enter at least one RFID.</p><fieldset ${canEdit()?'':'disabled'}><div class="animal-form-grid">${input('name','Animal name / reference (optional)',r.name)}${select('species','Animal type','species',species)}${input('tag1','RFID 1',r.tag1)}${input('tag2','RFID 2',r.tag2)}${select('breed','Breed','breeds',r.breed)}${select('sex','Gender / sex','sex_values',r.sex)}${select('stage','Lifecycle stage','lifecycle_stages',r.stage)}${select('shedTag','Shed / stage tag','shed_tags',r.shedTag)}${input('weightKg','Weight (kg)',r.weightKg,'number')}${select('park','Park','parks',park)}${select('pen','Pen','pens',r.parentId,park)}<label>Status<select id="animal-active"><option value="true" ${r.active!==false?'selected':''}>Active</option><option value="false" ${r.active===false?'selected':''}>Archived</option></select></label></div>${animalLocationSetup('form',park)}<label>Notes<textarea id="animal-notes" rows="2">${esc(r.notes||'')}</textarea></label></fieldset><p id="animal-form-error" class="error" role="alert"></p><div class="actions"><button type="button" onclick="closeModal()">Close</button>${canEdit()?'<button class="primary" type="submit">Save animal</button>':''}</div></form>`,true);$('#overlay .modal')?.classList.add('animal-form');animalLocationHint();}
function animalRefreshOptions(changed){if(changed==='species'){for(const [key,kind] of [['breed','breeds'],['stage','lifecycle_stages'],['shedTag','shed_tags']])$('#animal-'+key).innerHTML='<option value="">Choose…</option>'+animalSelectOptions(kind,'',$('#animal-species').value);}else {$('#animal-pen').innerHTML='<option value="">Choose…</option>'+animalSelectOptions('pens','','',$('#animal-park').value);const pick=$('#animal-form-location-park');if(pick)pick.value=$('#animal-park').value;animalLocationHint();}}
function animalSave(){if(!canEdit())return;try{const d=structuredClone(entityRegistryData()),old=EntityRegistryModel.rows(d,'animals').find(r=>r.id===animalEditingId),species=$('#animal-species').value;const raw={animal_name:$('#animal-name').value,animal_identifier_1:$('#animal-tag1').value,animal_identifier_2:$('#animal-tag2').value,species_id:species,breed:$('#animal-breed').value,sex:$('#animal-sex').value,stage:$('#animal-stage').value,shed_tag:$('#animal-shedTag').value,park:$('#animal-park').value,pen:$('#animal-pen').value,weight_kg:$('#animal-weightKg').value,notes:$('#animal-notes').value};const saved=EntityRegistryModel.save(d,'animals',{...old,...AnimalRegisterModel.input(d,raw,species),id:animalEditingId});if($('#animal-active').value==='false')EntityRegistryModel.archive(d,'animals',saved.id);else saved.active=true;state.entityRegistry=d;persist();closeModal();renderItems();}catch(e){$('#animal-form-error').textContent=e.message;}}
function animalOpenImport(){if(!canEdit())return;animalRegisterMode='import';animalImportSpecies=animalRegisterSpecies;animalImportText='';animalImportPreview=null;renderAnimalImport();}
function animalImportType(id){animalImportSpecies=id;animalImportText='';animalImportPreview=null;renderAnimalImport();}
function renderAnimalImport(){const host=$('.records-content');host.classList.add('animal-register');host.innerHTML=`<div class="records-title"><div><span class="eyebrow">Herd Register</span><h2>Import animals</h2></div><button onclick="animalRegisterMode='list';renderAnimalRegister()">Back to register</button></div>${animalLocationSetup('import')}<section class="animal-import-steps"><label>1. Choose animal type<select onchange="animalImportType(this.value)"><option value="">Choose…</option>${animalSelectOptions('species',animalImportSpecies)}</select></label><div><h3>2. Download and fill</h3><div class="actions"><button onclick="animalDownload('workbook')" ${animalImportSpecies?'':'disabled'}>Download Excel template</button><button onclick="animalDownload('reference')" ${animalImportSpecies?'':'disabled'}>Download allowed values</button></div><p class="muted">Use configured names or IDs. Breed and stage choices match the selected animal type; each pen belongs to its park.</p></div><label>3. Upload completed Excel or CSV<input type="file" accept=".xlsx,.csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,text/csv" onchange="animalReadFile(this.files[0])" ${animalImportSpecies?'':'disabled'}></label></section><p id="animal-import-error" class="error" role="alert"></p><div id="animal-import-preview"></div>`;renderAnimalImportPreview();animalLocationHint('import');}
function animalDownload(kind){try{const d=entityRegistryData(),species=AnimalRegisterModel.species(d,animalImportSpecies);if(kind==='workbook'){XLSX.writeFile(AnimalRegisterModel.workbook(d,species.id),species.name.toLowerCase().replace(/[^a-z0-9]+/g,'-')+'-animals.xlsx');return;}const text=kind==='template'?AnimalRegisterModel.template(d,species.id):AnimalRegisterModel.reference(d,species.id);const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=species.name.toLowerCase().replace(/[^a-z0-9]+/g,'-')+'-animals-'+kind+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){$('#animal-import-error').textContent=e.message;}}
async function animalReadFile(file){animalImportPreview=null;animalImportText='';if(!file)return;const species=animalImportSpecies;try{if(file.size>5*1024*1024)throw Error('Choose a file under 5 MB.');const text=/\.xlsx$/i.test(file.name)?AnimalRegisterModel.readWorkbook(entityRegistryData(),await file.arrayBuffer(),species):await file.text();if(species!==animalImportSpecies)return;animalImportText=text;animalImportPreview=AnimalRegisterModel.preview(entityRegistryData(),text,species);$('#animal-import-error').textContent='';}catch(e){$('#animal-import-error').textContent=e.message;}renderAnimalImportPreview();}
function renderAnimalImportPreview(){const el=$('#animal-import-preview');if(!el)return;const preview=animalImportPreview;if(!preview){el.innerHTML='';return;}el.innerHTML=`<h3>${preview.rows.length} ${preview.rows.length===1?'row':'rows'} · ${preview.rows.filter(r=>r.error).length} ${preview.rows.filter(r=>r.error).length===1?'error':'errors'}</h3><div class="records-table-wrap"><table class="records-table"><thead><tr><th>Row</th><th>Animal</th><th>RFID 1</th><th>RFID 2</th><th>Result</th></tr></thead><tbody>${preview.rows.map(r=>`<tr><td>${r.line}</td><td>${esc(r.raw.animal_name)}</td><td>${esc(r.raw.animal_identifier_1)}</td><td>${esc(r.raw.animal_identifier_2)}</td><td class="${r.error?'error':''}">${esc(r.error||'Ready')}</td></tr>`).join('')}</tbody></table></div><button class="primary" onclick="animalCommitImport()" ${preview.valid&&canEdit()?'':'disabled'}>Import ${preview.rows.length} ${preview.rows.length===1?'animal':'animals'}</button>`;}
function animalCommitImport(){if(!canEdit())return;try{state.entityRegistry=AnimalRegisterModel.commit(entityRegistryData(),animalImportText,animalImportSpecies);persist();animalRegisterMode='list';animalImportPreview=null;animalImportText='';renderItems();toast('Animals imported in this browser');}catch(e){$('#animal-import-error').textContent=e.message;}}

function animalLocationSetup(context,park=''){return `<section class="animal-location-setup"><p id="animal-${context}-location-hint" role="status"></p>${canEdit()?`<div class="animal-location-actions"><details><summary>+ Add park</summary><div class="animal-location-fields"><label>Park name<input id="animal-${context}-new-park" placeholder="Enter park name"></label><button type="button" onclick="animalCreateLocation('${context}','parks')">Create park</button></div></details><details><summary>+ Add pen</summary><div class="animal-location-fields"><label>Park *<select id="animal-${context}-location-park"><option value="">Choose park…</option>${animalSelectOptions('parks',park)}</select></label><label>Pen name *<input id="animal-${context}-new-pen" placeholder="Enter pen name"></label><button type="button" onclick="animalCreateLocation('${context}','pens')">Create pen</button></div></details></div>`:''}<p id="animal-${context}-location-error" class="error" role="alert"></p></section>`;}
function animalLocationHint(context='form'){const d=entityRegistryData(),parks=AnimalRegisterModel.options(d,'parks'),park=context==='form'?$('#animal-park')?.value:'',pens=AnimalRegisterModel.options(d,'pens').filter(p=>parks.some(a=>a.id===p.parentId)&&(!park||p.parentId===park));const el=$('#animal-'+context+'-location-hint');if(el)el.textContent=!parks.length?'Create a park and pen below before saving or importing animals.':!pens.length?'No pens configured'+(park?' in this park':'')+'. Add a pen below to continue.':context==='import'?'Use a configured park and its pen in every row. Add missing locations here before downloading the template.':'Park and pen are required. Add a missing location here without leaving this form.';}
function animalCreateLocation(context,kind){if(!canEdit())return;try{const name=$('#animal-'+context+'-new-'+(kind==='parks'?'park':'pen')).value,parent=kind==='pens'?$('#animal-'+context+'-location-park').value:'',result=AnimalRegisterModel.location(entityRegistryData(),kind,name,parent);state.entityRegistry=result.data;persist();const park=kind==='parks'?result.record.id:parent;$('#animal-'+context+'-location-park').innerHTML='<option value="">Choose park…</option>'+animalSelectOptions('parks',park);if(context==='form'){$('#animal-park').innerHTML='<option value="">Choose…</option>'+animalSelectOptions('parks',park);$('#animal-pen').innerHTML='<option value="">Choose…</option>'+animalSelectOptions('pens',kind==='pens'?result.record.id:'','',park);}$('#animal-'+context+'-new-'+(kind==='parks'?'park':'pen')).value='';$('#animal-'+context+'-location-error').textContent='';animalLocationHint(context);if(context==='import'&&animalImportText){animalImportPreview=AnimalRegisterModel.preview(entityRegistryData(),animalImportText,animalImportSpecies);renderAnimalImportPreview();}toast((kind==='parks'?'Park':'Pen')+' created');}catch(e){$('#animal-'+context+'-location-error').textContent=e.message;}}
